(()=>{const out={};for(const property of ['-webkit-border-before','-webkit-border-after','-webkit-border-start','-webkit-border-end','-webkit-text-stroke']){out[property]={};for(const value of ['none','auto','initial','1px solid red','red solid 1px','2px','0','thin','medium','thick','-1px','20%','red','transparent','currentcolor','rebeccapurple','#f00','#abcd','#12345678','rgb(10, 20, 30)','rgba(10, 20, 30, 0.5)','dashed blue','solid dotted','red blue','1px 2px','bogus']){const s=document.createElement('div').style;s.setProperty(property,value);out[property][value]={text:s.cssText,value:s.getPropertyValue(property),supported:CSS.supports(property,value),components:Array.from({length:s.length},(_,i)=>[s.item(i),s.getPropertyValue(s.item(i))])};}}return out})()
